<?php

namespace Database\Seeders;

use BezhanSalleh\FilamentShield\Facades\FilamentShield;
use BezhanSalleh\FilamentShield\Support\Utils;
use Filament\Facades\Filament;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Seeder;
use Illuminate\Support\Once;
use Spatie\Permission\PermissionRegistrar;

/**
 * Create every permission that the role editor offers, as generated by Shield from `config/filament-shield.php` (the
 * ones checked by the policies), and give them all to the `super_admin` role.
 *
 * It only adds what is missing, so that `och:install` can run it on every deployment. Shield reads the resources of the
 * current panel, so the `app` panel is made current meanwhile: the setup wizard runs this seeder from its own panel.
 * Shield keeps what it found with `once()` for the whole request, so that cache is cleared before and after.
 */
class ShieldSeeder extends Seeder
{
    public function run(): void
    {
        $currentPanel = Filament::getCurrentPanel();
        Filament::setCurrentPanel('app');
        Once::flush();

        try {
            $this->seedPermissions();
        } finally {
            Filament::setCurrentPanel($currentPanel);
            Once::flush();
        }

        $this->command?->info('Shield Seeding Completed.');
    }

    private function seedPermissions(): void
    {
        app(PermissionRegistrar::class)->forgetCachedPermissions();

        $guard = Utils::getFilamentAuthGuard();

        /** @var class-string<Model> $permissionModel */
        $permissionModel = Utils::getPermissionModel();

        $permissions = collect(static::permissionNames())
            ->map(fn (string $permission) => $permissionModel::firstOrCreate(['name' => $permission, 'guard_name' => $guard]))
            ->all();

        /** @var class-string<Model> $roleModel */
        $roleModel = Utils::getRoleModel();

        $roleModel::firstOrCreate(['name' => Utils::getSuperAdminName(), 'guard_name' => $guard])
            ->syncPermissions($permissions);
    }

    /**
     * The names of the permissions offered by the role editor (of the current panel).
     *
     * @return list<string>
     */
    public static function permissionNames(): array
    {
        return array_values(array_unique(FilamentShield::getEntitiesPermissions() ?? []));
    }
}
